int skip_id3_tag(SF_PRIVATE *psf)
{
    unsigned char header[10];
    size_t bytesRead;

    if (psf == NULL)
        return 0;

    // Read the first 10 bytes of the file
    bytesRead = fread(header, sizeof(unsigned char), 10, psf->file);

    if (bytesRead != 10)
        return 0;

    // Check for the ID3 tag header "ID3"
    if (header[0] != 'I' || header[1] != 'D' || header[2] != '3')
        return 0;

    // Calculate the size of the ID3 tag
    int size = 0;
    for (int i = 6; i <= 9; i++)
        size = (size << 8) | (header[i] & 0xFF);

    // Update the file offset
    size += 10; // Add 10 for the header bytes

    if (size > psf->filelength)
        return 0;

    // Seek to the end of the ID3 tag
    fseek(psf->file, size, SEEK_SET);
    psf->fileoffset = size;

    return 1;
}

int skip_id3_tag(SF_PRIVATE *psf) {
    uint8_t header[10];
    uint32_t tag_length;
    int64_t file_length;

    if (psf->filelength < 10)
        return 0;

    if (sf_readf_short(psf, header, 10) != 10)
        return 0;

    if (header[0] != 'I' || header[1] != 'D' || header[2] != '3')
        return 0;

    tag_length = ((uint32_t) header[6] << 21) |
                 ((uint32_t) header[7] << 14) |
                 ((uint32_t) header[8] << 7) |
                 header[9];

    file_length = psf->filelength;
    tag_length += 10;

    if (tag_length > file_length)
        return 0;

    psf->fileoffset = tag_length;

    return 1;
}

int skip_id3_tag(SF_PRIVATE *psf) {
    sf_count_t file_length = psf->filelength;
    sf_count_t offset = 0;
    char header[10];

    /* Read first 10 bytes to check for ID3 tag */
    if (psf_fread(header, 1, 10, psf) != 10)
        return 0;

    if (memcmp(header, "ID3", 3) != 0)
        return 0;

    /* Calculate length of ID3 tag */
    offset = (header[6] & 0x7f) << 21;
    offset |= (header[7] & 0x7f) << 14;
    offset |= (header[8] & 0x7f) << 7;
    offset |= (header[9] & 0x7f);

    /* Add 10 bytes for the header */
    offset += 10;

    /* Update the file offset */
    if (offset > file_length)
        return 0;

    psf->file = psf_fseek(psf->file, offset, SEEK_SET);
    psf->fileposition = offset;

    return 1;
}

