        return 0;

    if (fread(header, 1, 10, psf->file) != 10)
        return 0;

    if (header[0] == 'I' && header[1] == 'D' && header[2] == '3')
    {
        int size = 0;
        int i;

        for (i = 7; i < 10; i++)
        {
            size = (size << 8) | (header[i] & 0xFF);
        }

        size += 10; // Add the size of the header

        if (size > psf->filelength)
            return 0;

        psf->fileoffset = size;
        result = 1;
