int skip_id3_tag(SF_PRIVATE *psf)
{
    SF_PRIVATE id3_header;
    sf_count_t file_length = psf->filelength;
    sf_count_t id3_length = 0;
    sf_count_t new_position = 0;

    /* Read the ID3 header (first 10 bytes) */
    if (psf->file_position != 0)
        return 0;

    if (psf_fread(&id3_header, sizeof(id3_header), 1, psf) != 1)
        return 0;

    /* Check if it's an ID3 tag by checking the first 3 bytes */
    if (strncmp((char *)&id3_header, "ID3", 3) != 0)
        return 1;

    /* Calculate the length of the ID3 tag (the length is in bytes 6-10) */
    id3_length = ((id3_header.byte6 & 0x7F) << 21)
               | ((id3_header.byte7 & 0x7F) << 14)
               | ((id3_header.byte8 & 0x7F) << 7)
               | (id3_header.byte9 & 0x7F);

    new_position = id3_length + 10;

    /* Ensure the new position does not exceed the file length */
    if (new_position > file_length)
        return 0;

    /* Update the file position */
    if (psf_seek(psf, new_position, NULL) != SF_SUCCESS)
        return 0;

    return 1;
}
